const body = $json.body || $json;
const required = ['event', 'stockpile_id', 'snapshot_url'];
const missing = required.filter((field) => !body[field]);
if (missing.length) {
  throw new Error(`Payload incompleto. Faltan: ${missing.join(', ')}`);
}
if (body.event !== 'stockpile_created') {
  throw new Error(`Evento no soportado: ${body.event}`);
}
return [{
  json: {
    stockpileId: body.stockpile_id,
    stockpileName: body.stockpile_name || 'Acopio',
    stockpileNumber: body.stockpile_number || '',
    clientEmail: body.client_email || '',
    clientName: body.client_name || 'cliente',
    businessName: body.business_name || 'OctopusTrack',
    snapshotUrl: body.snapshot_url,
    logoUrl: body.logo_url || '',
    footerText: body.footer_text || 'Este correo fue generado automáticamente por OctopusTrack.'
  }
}];

const data = $('Validar y normalizar payload').first().json;
const numberSuffix = data.stockpileNumber ? ` ${data.stockpileNumber}` : '';
const subject = `Resumen de Acopio — ${data.stockpileName}`;
const logo = data.logoUrl
  ? `<img src="${data.logoUrl}" alt="${data.businessName}" style="max-height:56px;margin-bottom:16px;" />`
  : '';
const html = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;line-height:1.5;max-width:640px;margin:0 auto;">
  ${logo}
  <h1 style="font-size:22px;margin:0 0 12px;color:#111827;">Resumen de acopio${numberSuffix}</h1>
  <p>Hola ${data.clientName},</p>
  <p>Te enviamos adjunto el Excel con los precios congelados del acopio <strong>${data.stockpileName}</strong> de <strong>${data.businessName}</strong>.</p>
  <p>Estos precios corresponden al momento de creación del acopio y se usarán como referencia para los retiros posteriores.</p>
  <table style="width:100%;border-collapse:collapse;margin:20px 0;background:#f9fafb;border:1px solid #e5e7eb;">
    <tr><td style="padding:10px;font-weight:bold;">Acopio</td><td style="padding:10px;">${data.stockpileName}</td></tr>
    <tr><td style="padding:10px;font-weight:bold;">Número</td><td style="padding:10px;">${data.stockpileNumber || 'Sin número informado'}</td></tr>
    <tr><td style="padding:10px;font-weight:bold;">Comercio</td><td style="padding:10px;">${data.businessName}</td></tr>
  </table>
  <p>Si necesitás reenviar el archivo, podés hacerlo desde la pantalla de Acopios en OctopusTrack.</p>
  <p style="font-size:13px;color:#6b7280;border-top:1px solid #e5e7eb;padding-top:16px;">${data.footerText}</p>
</div>`;
return [{ json: { ...data, subject, html }, binary: $input.first().binary }];
